"use client";
import { create } from "zustand";
import { Chat, Message, ChatFolder, UserStories } from "@/types";
import { mockChats, mockMessages, mockFolders, mockStories } from "@/lib/mock-data";

interface ChatState {
  chats: Chat[];
  messages: Record<string, Message[]>;
  activeChatId: string | null;
  activeThreadId: string | null;
  folders: ChatFolder[];
  activeFolderId: string | null;
  stories: UserStories[];
  searchQuery: string;
  replyingTo: Message | null;
  editingMessage: Message | null;
  showProfile: boolean;
  showStickers: boolean;
  showCalls: boolean;
  showSettings: boolean;
  showPremium: boolean;
  showThread: boolean;

  setActiveChat: (chatId: string | null) => void;
  setActiveFolder: (folderId: string | null) => void;
  setSearchQuery: (q: string) => void;
  setReplyingTo: (msg: Message | null) => void;
  setEditingMessage: (msg: Message | null) => void;
  toggleProfile: () => void;
  toggleStickers: () => void;
  toggleCalls: () => void;
  toggleSettings: () => void;
  togglePremium: () => void;
  toggleThread: () => void;
  sendMessage: (chatId: string, text: string, type?: string) => void;
  addReaction: (chatId: string, messageId: string, emoji: string) => void;
  markAsRead: (chatId: string) => void;
  pinMessage: (chatId: string, messageId: string) => void;
  deleteMessage: (chatId: string, messageId: string) => void;
  toggleTranslation: (chatId: string) => void;
  viewStory: (storyId: string) => void;
}

let msgCounter = 5000;

export const useChatStore = create<ChatState>((set, get) => ({
  chats: mockChats,
  messages: mockMessages,
  activeChatId: null,
  activeThreadId: null,
  folders: mockFolders,
  activeFolderId: null,
  stories: mockStories,
  searchQuery: "",
  replyingTo: null,
  editingMessage: null,
  showProfile: false,
  showStickers: false,
  showCalls: false,
  showSettings: false,
  showPremium: false,
  showThread: false,

  setActiveChat: (chatId) => {
    set({ activeChatId: chatId, showProfile: false, showThread: false, replyingTo: null, editingMessage: null });
    if (chatId) get().markAsRead(chatId);
  },

  setActiveFolder: (folderId) => set({ activeFolderId: folderId }),
  setSearchQuery: (q) => set({ searchQuery: q }),
  setReplyingTo: (msg) => set({ replyingTo: msg, editingMessage: null }),
  setEditingMessage: (msg) => set({ editingMessage: msg, replyingTo: null }),
  toggleProfile: () => set((s) => ({ showProfile: !s.showProfile })),
  toggleStickers: () => set((s) => ({ showStickers: !s.showStickers })),
  toggleCalls: () => set((s) => ({ showCalls: !s.showCalls })),
  toggleSettings: () => set((s) => ({ showSettings: !s.showSettings })),
  togglePremium: () => set((s) => ({ showPremium: !s.showPremium })),
  toggleThread: () => set((s) => ({ showThread: !s.showThread })),

  sendMessage: (chatId, text, type = "text") => {
    const now = new Date();
    const msg: Message = {
      id: `msg-${++msgCounter}`,
      chatId,
      senderId: "me",
      senderName: "Ilya",
      text,
      type: type as Message["type"],
      timestamp: now.toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit" }),
      date: now.toISOString().split("T")[0],
      status: "sent",
      replyTo: get().replyingTo ? { id: get().replyingTo!.id, senderId: get().replyingTo!.senderId, senderName: get().replyingTo!.senderName || "", text: get().replyingTo!.text, type: get().replyingTo!.type } : undefined,
    };
    set((s) => ({
      messages: { ...s.messages, [chatId]: [...(s.messages[chatId] || []), msg] },
      chats: s.chats.map((c) => c.id === chatId ? { ...c, lastMessage: { text, senderId: "me", timestamp: msg.timestamp, type: msg.type as Message["type"] }, unreadCount: 0 } : c),
      replyingTo: null,
      editingMessage: null,
    }));
    // Simulate delivery + read
    setTimeout(() => set((s) => ({ messages: { ...s.messages, [chatId]: (s.messages[chatId] || []).map((m) => m.id === msg.id ? { ...m, status: "delivered" } : m) } })), 1000);
    setTimeout(() => set((s) => ({ messages: { ...s.messages, [chatId]: (s.messages[chatId] || []).map((m) => m.id === msg.id ? { ...m, status: "read" } : m) } })), 2500);
    // Simulate auto-reply
    const replies = ["Ok!", "Got it", "Interesting", "Will check", "Thanks!", "Sure thing"];
    const chat = get().chats.find((c) => c.id === chatId);
    if (chat?.type === "direct" && chat.user) {
      setTimeout(() => {
        const replyText = replies[Math.floor(Math.random() * replies.length)];
        const replyTime = new Date();
        const reply: Message = {
          id: `msg-${++msgCounter}`, chatId, senderId: chat.user!.id, senderName: chat.user!.name, text: replyText,
          type: "text", timestamp: replyTime.toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit" }),
          date: replyTime.toISOString().split("T")[0], status: "read",
        };
        set((s) => ({
          messages: { ...s.messages, [chatId]: [...(s.messages[chatId] || []), reply] },
          chats: s.chats.map((c) => c.id === chatId ? { ...c, lastMessage: { text: replyText, senderId: reply.senderId, timestamp: reply.timestamp, type: "text" } } : c),
        }));
      }, 2000 + Math.random() * 2000);
    }
  },

  addReaction: (chatId, messageId, emoji) => {
    set((s) => ({
      messages: {
        ...s.messages,
        [chatId]: (s.messages[chatId] || []).map((m) => {
          if (m.id !== messageId) return m;
          const reactions = [...(m.reactions || [])];
          const existing = reactions.find((r) => r.emoji === emoji);
          if (existing) {
            if (existing.myReaction) { existing.count--; existing.myReaction = false; existing.users = existing.users.filter((u) => u !== "me"); }
            else { existing.count++; existing.myReaction = true; existing.users.push("me"); }
          } else { reactions.push({ emoji, count: 1, users: ["me"], myReaction: true }); }
          return { ...m, reactions: reactions.filter((r) => r.count > 0) };
        }),
      },
    }));
  },

  markAsRead: (chatId) => set((s) => ({ chats: s.chats.map((c) => c.id === chatId ? { ...c, unreadCount: 0 } : c) })),

  pinMessage: (chatId, messageId) => {
    set((s) => ({
      messages: { ...s.messages, [chatId]: (s.messages[chatId] || []).map((m) => m.id === messageId ? { ...m, isPinned: !m.isPinned } : m) },
    }));
  },

  deleteMessage: (chatId, messageId) => {
    set((s) => ({
      messages: { ...s.messages, [chatId]: (s.messages[chatId] || []).filter((m) => m.id !== messageId) },
    }));
  },

  toggleTranslation: (chatId) => {
    set((s) => ({
      chats: s.chats.map((c) => c.id === chatId ? { ...c, autoTranslate: !c.autoTranslate } : c),
    }));
  },

  viewStory: (storyId) => {
    set((s) => ({
      stories: s.stories.map((us) => ({
        ...us,
        stories: us.stories.map((st) => st.id === storyId ? { ...st, isViewed: true, viewsCount: st.viewsCount + 1 } : st),
        hasUnviewed: us.stories.some((st) => st.id !== storyId && !st.isViewed),
      })),
    }));
  },
}));
