"use client";
import { create } from "zustand";
import { User } from "@/types";

interface AuthState {
  user: User | null;
  token: string | null;
  isLoading: boolean;
  language: string;
  login: (phone: string, password: string) => Promise<boolean>;
  register: (name: string, phone: string, password: string, language: string, username: string) => Promise<boolean>;
  logout: () => void;
  setLanguage: (lang: string) => void;
  setUsername: (username: string) => void;
  hydrate: () => void;
}

export const useAuthStore = create<AuthState>((set, get) => ({
  user: null,
  token: null,
  isLoading: true,
  language: "ru",

  hydrate: () => {
    const stored = localStorage.getItem("tepla-auth");
    if (stored) {
      const data = JSON.parse(stored);
      set({ user: data.user, token: data.token, language: data.language || "ru", isLoading: false });
    } else {
      set({ isLoading: false });
    }
  },

  login: async (phone, password) => {
    set({ isLoading: true });
    await new Promise((r) => setTimeout(r, 800));
    if (password.length < 6) { set({ isLoading: false }); return false; }
    const user: User = { id: "me", name: "Ilya", username: "ilya", status: "online", isPremium: true, language: get().language };
    const token = "mock-jwt-token";
    localStorage.setItem("tepla-auth", JSON.stringify({ user, token, language: get().language }));
    set({ user, token, isLoading: false });
    return true;
  },

  register: async (name, phone, _password, language, username) => {
    set({ isLoading: true });
    await new Promise((r) => setTimeout(r, 800));
    const user: User = { id: "me", name, username, status: "online", language, phone };
    const token = "mock-jwt-token";
    localStorage.setItem("tepla-auth", JSON.stringify({ user, token, language }));
    set({ user, token, isLoading: false, language });
    return true;
  },

  logout: () => {
    localStorage.removeItem("tepla-auth");
    set({ user: null, token: null });
  },

  setLanguage: (lang) => {
    set({ language: lang });
    const stored = localStorage.getItem("tepla-auth");
    if (stored) {
      const data = JSON.parse(stored);
      data.language = lang;
      localStorage.setItem("tepla-auth", JSON.stringify(data));
    }
  },

  setUsername: (username) => {
    const { user } = get();
    if (!user) return;
    const updated = { ...user, username };
    set({ user: updated });
    const stored = localStorage.getItem("tepla-auth");
    if (stored) {
      const data = JSON.parse(stored);
      data.user = updated;
      localStorage.setItem("tepla-auth", JSON.stringify(data));
    }
  },
}));
